package com.smile.smile_app

import android.content.Context
import android.media.AudioAttributes
import android.media.SoundPool

/**
 * The Frame's chime when new photos arrive (2026-10-28, Ernst: Ton C,
 * "Dreiklang", generated by tools/sounds/make3.js). On the media volume --
 * the one a Frame's videos use, so it is up on a Frame.
 */
class FrameChime(context: Context) {
    private val pool = SoundPool.Builder()
        .setMaxStreams(1)
        .setAudioAttributes(
            AudioAttributes.Builder()
                .setUsage(AudioAttributes.USAGE_MEDIA)
                .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION)
                .build()
        )
        .build()
    private val chime = pool.load(context, R.raw.frame_new, 1)

    fun play() {
        pool.play(chime, 1f, 1f, 1, 0, 1f)
    }

    fun release() = pool.release()
}
